pub fn template_fields_for_station(station: u16) -> &'static [TemplateField] {
    let index = station as usize % SUPPLY_FIELD_SETS.len();
    SUPPLY_FIELD_SETS[index]
}

pub fn severity_for_field(code: u16) -> u8 {
    match code & 0x000f {
        0 | 1 => 2,
        2 | 3 => 5,
        4 | 5 => 8,
        6 | 7 => 13,
        _ => 3,
    }
}
